-- Companies that could offset budget lines (laptops, monitors, controllers, travel, lodging, licensing, software, snacks).
-- NOT verified. verified=false, to_research. Dry run: change the last line to rollback;
begin;
insert into fs_grant_deadlines (funder, program, kind, url, level, project, priority, eligibility, notes, gates, next_step, active, verified, status)
select v.funder, v.program, v.kind, v.url, v.level, v.project, v.priority, v.eligibility, v.notes, v.gates, 'Read their giving or sponsorship process and find a contact. The ask: ' || v.ask, true, false, 'to_research'
from (values
('Apple','Education and community (laptops)','relationship','https://www.apple.com/','corporate','djclass',1,'Unconfirmed','Budget line this could offset: Laptops: 13 MacBook Pro 14-inch, about $20,787. Apple Community Education Initiative and education pricing are leads from general knowledge; a quick search could not confirm a current Chicago grant. Verify.','{g1,g4}'::text[],'Corporate giving - in-kind','Ask for MacBook Pro laptops (or education pricing) for the 12 student stations and a spare, with a local Apple Store or education rep as the first door.'),
('Best Buy / Best Buy Foundation','Teen Tech Centers (our partner Gary Comer is a Best Buy Teen Tech Center)','relationship','https://www.bestbuy.com/','corporate','djclass',1,'Unconfirmed','Budget line this could offset: Laptops, monitors, headphones: up to about $23,000. Introduction via Terrance Patterson at the Teen Tech Center once the Park District green light is in. Verify the program.','{g4}'::text[],'Corporate giving - in-kind','Ask through the Teen Tech Center connection (Gary Comer Youth Center) for an introduction to Best Buy''s community team; target monitors, laptops, headphones.'),
('Dell Technologies','Community and education giving','relationship','https://www.dell.com/','corporate','djclass',2,'Unconfirmed','Budget line this could offset: Monitors: 13 about $145 = $1,885. General knowledge. Verify the giving channel.','{g1,g4}'::text[],'Corporate giving - in-kind','Ask for 13 24-inch monitors with cables.'),
('Samsung','Community and education giving','relationship','https://www.samsung.com/us/','corporate','djclass',3,'Unconfirmed','Budget line this could offset: Monitors: about $1,885. General knowledge. Verify.','{g4}'::text[],'Corporate giving - in-kind','Ask for 13 monitors with cables.'),
('LG Electronics USA','Community and education giving','relationship','https://www.lg.com/us','corporate','djclass',3,'Unconfirmed','Budget line this could offset: Monitors: about $1,885. General knowledge. Verify.','{g4}'::text[],'Corporate giving - in-kind','Ask for 13 monitors with cables.'),
('Amazon (Chicago community and Amazon in the Community)','Community giving and event sponsorship','relationship','https://www.aboutamazon.com/','corporate','djclass',2,'Unconfirmed','Budget line this could offset: Cooling stands, cables, headphones, power strips: about $1,500 plus monitors. Stephen reports Amazon sponsored Chicago Halloween events; a quick search found no evidence. Verify before citing.','{g1,g4}'::text[],'Corporate giving - in-kind','Ask Amazon''s Chicago community team for a gear donation (cooling stands, cables, headphones, power) and sponsor recognition at a Showcase.'),
('Goodwill Greater Milwaukee & Chicago','Community partnerships and event sponsorship','relationship',null,null,'djclass',2,'Unconfirmed','Budget line this could offset: Tables, costumes for Halloween and holiday parties, supplies. Presented The Haunted Runway, a DIY costume contest, at Arts in the Dark (Oct 2025), per a search result. Stephen reports it as a major Chicago Halloween sponsor. Verify.','{g4}'::text[],'Corporate giving - in-kind','Ask for a partnership: tables and furnishings for the stations, costume support for the family parties, and sponsor recognition.'),
('Barry Callebaut','Halloweek sponsor (Chicago)','relationship','https://www.barry-callebaut.com/','corporate','djclass',3,'Unconfirmed','Budget line this could offset: Snacks: $20 x 15 people x 39 Tuesdays = $11,700. Reported as a lead sponsor of Chicago''s Halloweek and Arts in the Dark (search result, undated). Verify the Chicago presence and giving process.','{g4}'::text[],'Corporate giving - in-kind','Ask for snack or chocolate donations for Tuesday classes and the family parties.'),
('United Airlines','Community giving; Miles on a Mission','relationship','https://www.united.com/','corporate','djclass',1,'Unconfirmed','Budget line this could offset: Guest DJ travel: $25/week allowance plus out-of-town guest flights. Chicago headquarters. One third-party source says United does not take unsolicited requests and chooses partners by invitation; Miles on a Mission is its public channel. Verify on united.com.','{g1,g4}'::text[],'Travel and lodging','Ask for donated tickets or miles to fly guest woman DJs to Chicago, and consider Miles on a Mission for a miles-raising campaign.'),
('American Airlines','Community giving (O''Hare hub)','relationship','https://www.aa.com/','corporate','djclass',2,'Unconfirmed','Budget line this could offset: Guest DJ flights into O''Hare. General knowledge. Verify the request process.','{g4}'::text[],'Travel and lodging','Ask for donated tickets for out-of-town guest DJs.'),
('Southwest Airlines','Community giving (Midway)','relationship','https://www.southwest.com/','corporate','djclass',2,'Unconfirmed','Budget line this could offset: Guest DJ flights into Midway (nearest to the South Side). General knowledge. Verify the request process.','{g4}'::text[],'Travel and lodging','Ask for donated tickets for out-of-town guest DJs.'),
('Delta Air Lines','Community giving','relationship','https://www.delta.com/','corporate','djclass',3,'Unconfirmed','Budget line this could offset: Guest DJ flights. General knowledge. Verify the request process.','{g4}'::text[],'Travel and lodging','Ask for donated tickets for out-of-town guest DJs.'),
('Hilton','Community giving and room donations','relationship','https://www.hilton.com/','corporate','djclass',2,'Unconfirmed','Budget line this could offset: Guest DJ lodging. General knowledge. Verify.','{g4}'::text[],'Travel and lodging','Ask for donated room nights for out-of-town guest DJs.'),
('Marriott International','Community giving and room donations','relationship','https://www.marriott.com/','corporate','djclass',3,'Unconfirmed','Budget line this could offset: Guest DJ lodging. General knowledge. Verify.','{g4}'::text[],'Travel and lodging','Ask for donated room nights for out-of-town guest DJs.'),
('IHG Hotels & Resorts (Kimpton and others)','Community giving and room donations','relationship','https://www.ihg.com/','corporate','djclass',3,'Unconfirmed','Budget line this could offset: Guest DJ lodging. General knowledge. Verify.','{g4}'::text[],'Travel and lodging','Ask for donated room nights for out-of-town guest DJs.'),
('Lyft','Community partnerships','relationship','https://www.lyft.com/','corporate','djclass',3,'Unconfirmed','Budget line this could offset: Guest travel allowance ($25 a week) and rides. General knowledge. Verify.','{g4}'::text[],'Travel and lodging','Ask for ride credits to bring guest DJs and families to Rainbow Beach.'),
('Uber','Community partnerships','relationship','https://www.uber.com/','corporate','djclass',3,'Unconfirmed','Budget line this could offset: Guest travel allowance ($25 a week) and rides. General knowledge. Verify.','{g4}'::text[],'Travel and lodging','Ask for ride credits to bring guest DJs and families to Rainbow Beach.'),
('ASCAP Foundation','Music education and licensing','relationship','https://www.ascap.com/','foundation','djclass',2,'Unconfirmed','Budget line this could offset: Music public-performance licensing reserve: $1,000. General knowledge. Verify.','{g1,g4}'::text[],'Music licensing','Ask about a licensing waiver or youth-education discount for the DJ Lab, and about their grants.'),
('BMI Foundation','Music education and licensing','relationship','https://www.bmi.com/','foundation','djclass',2,'Unconfirmed','Budget line this could offset: Music public-performance licensing reserve: $1,000. General knowledge. Verify.','{g1,g4}'::text[],'Music licensing','Ask about a licensing waiver or youth-education discount for the DJ Lab, and about their grants.'),
('Serato','Education licensing','relationship','https://serato.com/','corporate','djclass',2,'Unconfirmed','Budget line this could offset: DJ software for 13 stations. General knowledge. Verify.','{g4}'::text[],'Software','Ask for education or donated licenses for 13 stations.'),
('Algoriddim (djay)','Education licensing (Apple-focused DJ software)','relationship','https://www.algoriddim.com/','corporate','djclass',2,'Unconfirmed','Budget line this could offset: DJ software for 13 Apple stations. General knowledge. Verify.','{g4}'::text[],'Software','Ask for education or donated licenses for 13 MacBook stations.')
) as v(funder, program, kind, url, level, project, priority, eligibility, notes, gates, category, ask)
where not exists (select 1 from fs_grant_deadlines d where lower(d.funder) = lower(v.funder));
select (select count(*) from fs_grant_deadlines) funders, (select count(*) from fs_partners) partners;
commit;
